// Extract Entities & Relations from documents using NLP
// This code processes text to identify key concepts, people, places, and their connections

const item = $input.item.json;
const text = item.content || item.text || item.body || '';

// Simple entity extraction patterns
const entityPatterns = {
  person: /\b[A-Z][a-z]+ [A-Z][a-z]+\b/g, // Simple name pattern
  organization: /\b(?:Inc|Corp|LLC|Ltd|Company|Organization|University|Institute)\b/gi,
  location: /\b(?:New York|London|Paris|Tokyo|California|Texas|USA|UK|Canada)\b/gi,
  date: /\b(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4}|\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b/gi,
  technology: /\b(?:AI|artificial intelligence|machine learning|blockchain|cloud computing|API|database|software|algorithm)\b/gi
};

// Extract entities
const entities = [];
let entityId = 1;

for (const [type, pattern] of Object.entries(entityPatterns)) {
  const matches = text.match(pattern) || [];
  for (const match of matches) {
    entities.push({
      id: `entity_${entityId++}`,
      text: match.trim(),
      type: type,
      confidence: 0.8
    });
  }
}

// Simple relationship extraction based on proximity and common patterns
const relations = [];
let relationId = 1;

// Look for relationships between entities
for (let i = 0; i < entities.length; i++) {
  for (let j = i + 1; j < entities.length; j++) {
    const entity1 = entities[i];
    const entity2 = entities[j];

    // Check if entities appear close to each other in text
    const entity1Index = text.indexOf(entity1.text);
    const entity2Index = text.indexOf(entity2.text);

    if (Math.abs(entity1Index - entity2Index) < 100) { // Within 100 characters
      let relationType = 'related_to';

      // Determine relationship type based on entity types
      if (entity1.type === 'person' && entity2.type === 'organization') {
        relationType = 'works_for';
      } else if (entity1.type === 'person' && entity2.type === 'location') {
        relationType = 'located_in';
      } else if (entity1.type === 'organization' && entity2.type === 'location') {
        relationType = 'based_in';
      } else if (entity1.type === 'person' && entity2.type === 'person') {
        relationType = 'knows';
      }

      relations.push({
        id: `relation_${relationId++}`,
        source: entity1.id,
        target: entity2.id,
        type: relationType,
        confidence: 0.7
      });
    }
  }
}

// Remove duplicate entities
const uniqueEntities = entities.filter((entity, index, self) => 
  index === self.findIndex(e => e.text.toLowerCase() === entity.text.toLowerCase() && e.type === entity.type)
);

// Return structured data
return {
  json: {
    document_id: item.id || `doc_${Date.now()}`,
    original_text: text,
    entities: uniqueEntities,
    relations: relations,
    extraction_timestamp: new Date().toISOString(),
    entity_count: uniqueEntities.length,
    relation_count: relations.length
  }
};

// Build Knowledge Graph from extracted entities and relations
const items = $input.all();

// Initialize graph structure
const graph = {
  nodes: new Map(),
  edges: [],
  metadata: {
    totalNodes: 0,
    totalEdges: 0,
    createdAt: new Date().toISOString()
  }
};

// Process each document's entities and relations
for (const item of items) {
  const { entities = [], relations = [], document = {} } = item.json;

  // Add entities as nodes
  entities.forEach(entity => {
    const nodeId = `${entity.type}_${entity.text.toLowerCase().replace(/\s+/g, '_')}`;

    if (!graph.nodes.has(nodeId)) {
      graph.nodes.set(nodeId, {
        id: nodeId,
        label: entity.text,
        type: entity.type,
        confidence: entity.confidence || 1.0,
        properties: {
          frequency: 1,
          documents: [document.id || document.title || 'unknown']
        }
      });
    } else {
      // Update existing node
      const node = graph.nodes.get(nodeId);
      node.properties.frequency += 1;
      if (!node.properties.documents.includes(document.id || document.title)) {
        node.properties.documents.push(document.id || document.title || 'unknown');
      }
    }
  });

  // Add relations as edges
  relations.forEach(relation => {
    const sourceId = `${relation.source.type}_${relation.source.text.toLowerCase().replace(/\s+/g, '_')}`;
    const targetId = `${relation.target.type}_${relation.target.text.toLowerCase().replace(/\s+/g, '_')}`;

    graph.edges.push({
      id: `${sourceId}_${relation.type}_${targetId}`,
      source: sourceId,
      target: targetId,
      type: relation.type,
      confidence: relation.confidence || 1.0,
      properties: {
        document: document.id || document.title || 'unknown'
      }
    });
  });
}

// Convert nodes Map to array
const nodesArray = Array.from(graph.nodes.values());
graph.nodes = nodesArray;
graph.metadata.totalNodes = nodesArray.length;
graph.metadata.totalEdges = graph.edges.length;

// Graph traversal and query capabilities
const graphUtils = {
  // Find nodes by type
  findNodesByType: (nodeType) => {
    return graph.nodes.filter(node => node.type === nodeType);
  },

  // Find connected nodes
  findConnectedNodes: (nodeId) => {
    const connectedEdges = graph.edges.filter(edge => 
      edge.source === nodeId || edge.target === nodeId
    );

    const connectedNodeIds = new Set();
    connectedEdges.forEach(edge => {
      if (edge.source !== nodeId) connectedNodeIds.add(edge.source);
      if (edge.target !== nodeId) connectedNodeIds.add(edge.target);
    });

    return graph.nodes.filter(node => connectedNodeIds.has(node.id));
  },

  // Find shortest path between two nodes
  findShortestPath: (startId, endId) => {
    const visited = new Set();
    const queue = [{ nodeId: startId, path: [startId] }];

    while (queue.length > 0) {
      const { nodeId, path } = queue.shift();

      if (nodeId === endId) {
        return path;
      }

      if (visited.has(nodeId)) continue;
      visited.add(nodeId);

      const connectedEdges = graph.edges.filter(edge => 
        edge.source === nodeId || edge.target === nodeId
      );

      connectedEdges.forEach(edge => {
        const nextNodeId = edge.source === nodeId ? edge.target : edge.source;
        if (!visited.has(nextNodeId)) {
          queue.push({ nodeId: nextNodeId, path: [...path, nextNodeId] });
        }
      });
    }

    return null; // No path found
  },

  // Query nodes by properties
  queryNodes: (queryFn) => {
    return graph.nodes.filter(queryFn);
  }
};

// Enrich original documents with graph metadata
const enrichedDocuments = items.map(item => {
  const { entities = [], relations = [], document = {} } = item.json;

  // Find related nodes in the graph
  const relatedNodes = [];
  entities.forEach(entity => {
    const nodeId = `${entity.type}_${entity.text.toLowerCase().replace(/\s+/g, '_')}`;
    const node = graph.nodes.find(n => n.id === nodeId);
    if (node) {
      relatedNodes.push(node);
    }
  });

  // Calculate document centrality (how connected it is in the graph)
  const documentCentrality = relatedNodes.reduce((sum, node) => {
    const connections = graph.edges.filter(edge => 
      edge.source === node.id || edge.target === node.id
    ).length;
    return sum + connections;
  }, 0);

  return {
    ...item.json,
    graphMetadata: {
      relatedNodes: relatedNodes.map(node => ({
        id: node.id,
        label: node.label,
        type: node.type,
        frequency: node.properties.frequency
      })),
      centrality: documentCentrality,
      entityCount: entities.length,
      relationCount: relations.length
    }
  };
});

// Return the complete knowledge graph and enriched documents
return [
  {
    json: {
      knowledgeGraph: graph,
      graphUtils: {
        findNodesByType: 'function',
        findConnectedNodes: 'function',
        findShortestPath: 'function',
        queryNodes: 'function'
      },
      enrichedDocuments: enrichedDocuments,
      summary: {
        totalDocuments: items.length,
        totalNodes: graph.metadata.totalNodes,
        totalEdges: graph.metadata.totalEdges,
        avgEntitiesPerDoc: entities.length / items.length,
        avgRelationsPerDoc: relations.length / items.length
      }
    }
  }
];

// Graph Query Tool - Query knowledge graph structure and discover relationships
// Input: query string containing entity names or relationship types to search for

// Parse the query to extract entities and relationship types
const queryLower = query.toLowerCase();
const entities = [];
const relationshipTypes = [];

// Extract potential entities (capitalized words or quoted phrases)
const entityMatches = query.match(/[A-Z][a-z]+|"[^"]+"/g);
if (entityMatches) {
  entities.push(...entityMatches.map(e => e.replace(/"/g, '')));
}

// Extract relationship keywords
const relationshipKeywords = ['related to', 'connected to', 'part of', 'causes', 'leads to', 'influences', 'depends on'];
relationshipKeywords.forEach(keyword => {
  if (queryLower.includes(keyword)) {
    relationshipTypes.push(keyword);
  }
});

// Mock knowledge graph structure (in real implementation, this would query actual graph database)
const knowledgeGraph = {
  nodes: [
    { id: 'entity1', label: 'Climate Change', type: 'concept' },
    { id: 'entity2', label: 'Carbon Emissions', type: 'factor' },
    { id: 'entity3', label: 'Renewable Energy', type: 'solution' },
    { id: 'entity4', label: 'Global Temperature', type: 'metric' },
    { id: 'entity5', label: 'Solar Power', type: 'technology' }
  ],
  edges: [
    { source: 'entity2', target: 'entity1', relationship: 'causes', weight: 0.9 },
    { source: 'entity3', target: 'entity2', relationship: 'reduces', weight: 0.8 },
    { source: 'entity1', target: 'entity4', relationship: 'affects', weight: 0.95 },
    { source: 'entity5', target: 'entity3', relationship: 'part of', weight: 0.7 }
  ]
};

// Graph traversal function to find paths between entities
function findPaths(startEntity, endEntity, maxDepth = 3) {
  const paths = [];
  const visited = new Set();

  function dfs(currentNode, targetNode, currentPath, depth) {
    if (depth > maxDepth) return;
    if (currentNode === targetNode && currentPath.length > 0) {
      paths.push([...currentPath]);
      return;
    }

    visited.add(currentNode);

    // Find outgoing edges from current node
    const outgoingEdges = knowledgeGraph.edges.filter(edge => edge.source === currentNode);

    for (const edge of outgoingEdges) {
      if (!visited.has(edge.target)) {
        currentPath.push({
          from: currentNode,
          to: edge.target,
          relationship: edge.relationship,
          weight: edge.weight
        });
        dfs(edge.target, targetNode, currentPath, depth + 1);
        currentPath.pop();
      }
    }

    visited.delete(currentNode);
  }

  const startNode = knowledgeGraph.nodes.find(n => n.label.toLowerCase().includes(startEntity.toLowerCase()));
  const endNode = knowledgeGraph.nodes.find(n => n.label.toLowerCase().includes(endEntity.toLowerCase()));

  if (startNode && endNode) {
    dfs(startNode.id, endNode.id, [], 0);
  }

  return paths;
}

// Find connected entities for a given entity
function findConnectedEntities(entityName) {
  const entity = knowledgeGraph.nodes.find(n => 
    n.label.toLowerCase().includes(entityName.toLowerCase())
  );

  if (!entity) return [];

  const connections = [];

  // Find outgoing connections
  knowledgeGraph.edges.forEach(edge => {
    if (edge.source === entity.id) {
      const targetNode = knowledgeGraph.nodes.find(n => n.id === edge.target);
      if (targetNode) {
        connections.push({
          entity: targetNode.label,
          relationship: edge.relationship,
          direction: 'outgoing',
          weight: edge.weight,
          type: targetNode.type
        });
      }
    }

    // Find incoming connections
    if (edge.target === entity.id) {
      const sourceNode = knowledgeGraph.nodes.find(n => n.id === edge.source);
      if (sourceNode) {
        connections.push({
          entity: sourceNode.label,
          relationship: edge.relationship,
          direction: 'incoming',
          weight: edge.weight,
          type: sourceNode.type
        });
      }
    }
  });

  return connections.sort((a, b) => b.weight - a.weight);
}

// Main query processing
let result = {
  query: query,
  entities_found: [],
  relationships: [],
  paths: [],
  connected_entities: []
};

// Process each identified entity
entities.forEach(entity => {
  const matchingNode = knowledgeGraph.nodes.find(n => 
    n.label.toLowerCase().includes(entity.toLowerCase())
  );

  if (matchingNode) {
    result.entities_found.push({
      name: matchingNode.label,
      type: matchingNode.type,
      id: matchingNode.id
    });

    // Find connected entities
    const connections = findConnectedEntities(entity);
    result.connected_entities.push({
      entity: matchingNode.label,
      connections: connections
    });
  }
});

// Find paths between entities if multiple entities are specified
if (entities.length >= 2) {
  for (let i = 0; i < entities.length - 1; i++) {
    for (let j = i + 1; j < entities.length; j++) {
      const paths = findPaths(entities[i], entities[j]);
      if (paths.length > 0) {
        result.paths.push({
          from: entities[i],
          to: entities[j],
          paths: paths
        });
      }
    }
  }
}

// If no specific entities found, return general graph statistics
if (result.entities_found.length === 0) {
  result.graph_summary = {
    total_nodes: knowledgeGraph.nodes.length,
    total_edges: knowledgeGraph.edges.length,
    node_types: [...new Set(knowledgeGraph.nodes.map(n => n.type))],
    relationship_types: [...new Set(knowledgeGraph.edges.map(e => e.relationship))]
  };
}

// Format the response as a readable string
let response = `Graph Query Results for: "${query}"\n\n`;

if (result.entities_found.length > 0) {
  response += `Found Entities:\n`;
  result.entities_found.forEach(entity => {
    response += `- ${entity.name} (${entity.type})\n`;
  });
  response += `\n`;
}

if (result.connected_entities.length > 0) {
  response += `Entity Relationships:\n`;
  result.connected_entities.forEach(item => {
    response += `\n${item.entity}:\n`;
    item.connections.forEach(conn => {
      response += `  ${conn.direction === 'outgoing' ? '→' : '←'} ${conn.relationship} ${conn.entity} (${conn.type}, weight: ${conn.weight})\n`;
    });
  });
  response += `\n`;
}

if (result.paths.length > 0) {
  response += `Relationship Paths:\n`;
  result.paths.forEach(pathGroup => {
    response += `\nPaths from ${pathGroup.from} to ${pathGroup.to}:\n`;
    pathGroup.paths.forEach((path, index) => {
      response += `  Path ${index + 1}: `;
      path.forEach((step, stepIndex) => {
        if (stepIndex > 0) response += ` → `;
        response += `${step.from} --[${step.relationship}]--> ${step.to}`;
      });
      response += `\n`;
    });
  });
}

if (result.graph_summary) {
  response += `Graph Overview:\n`;
  response += `- Total Nodes: ${result.graph_summary.total_nodes}\n`;
  response += `- Total Edges: ${result.graph_summary.total_edges}\n`;
  response += `- Node Types: ${result.graph_summary.node_types.join(', ')}\n`;
  response += `- Relationship Types: ${result.graph_summary.relationship_types.join(', ')}\n`;
}

return response;
